import * as React from "react";

import { cn } from "@/lib/utils";

const Input = React.forwardRef<HTMLInputElement, React.ComponentProps<"input">>(
  ({ className, type, id, name, placeholder, ...props }, ref) => {
    const autoId = React.useId();
    const resolvedId = id || (name ? `input-${name}` : autoId);
    const resolvedName = name || id || (placeholder ? placeholder.toLowerCase().replace(/[^a-z0-9_-]+/g, "-") : autoId);
    const ariaLabel = props["aria-label"] || (!props["aria-labelledby"] && placeholder ? placeholder : undefined);

    return (
      <input
        type={type}
        id={resolvedId}
        name={resolvedName}
        aria-label={ariaLabel}
        placeholder={placeholder}
        className={cn(
          "flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-base transition-colors file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:text-sm",
          className,
        )}
        ref={ref}
        {...props}
      />
    );
  },
);
Input.displayName = "Input";

export { Input };
